INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-r06-2024-q01','exam-sg','リスクマネジメント・リスクアセスメント','standard','single_choice','JIS Q 31000:2019（リスクマネジメント－指針）におけるリスクアセスメントを構成するプロセスの組合せはどれか。','[{"id":"a","text":"リスク特定，リスク評価，リスク受容"},{"id":"b","text":"リスク特定，リスク分析，リスク評価"},{"id":"c","text":"リスク分析，リスク対応，リスク受容"},{"id":"d","text":"リスク分析，リスク評価，リスク対応"}]','"b"','リスクアセスメントはリスク特定，リスク分析，リスク評価で構成される。リスク対応はアセスメント後のプロセスである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q02','exam-sg','情報管理・情報分類','standard','single_choice','情報の取扱基準の中で，社外秘情報の持出しを禁じ，周知した上で，従業員に情報を不正に持ち出された場合に，“社外秘情報とは知らなかった”という言い訳をさせないことが目的の一つになっている対策はどれか。','[{"id":"a","text":"権限がない従業員が文書にアクセスできないようにするペーパレス化"},{"id":"b","text":"従業員との信頼関係の維持を目的にした職場環境の整備"},{"id":"c","text":"従業員に対する電子メールの外部送信データ量の制限"},{"id":"d","text":"情報の管理レベルについてのラベル付け"}]','"d"','情報の機密区分をラベルで明示すると，取扱いルールを利用者に認識させ，情報の管理レベルに応じた運用を行いやすくなる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q03','exam-sg','マルウェア対策・検出手法','standard','single_choice','マルウェアの検出方法のうち，検査対象のプログラムを実行する必要があるものはどれか。','[{"id":"a","text":"コンペア法"},{"id":"b","text":"チェックサム法"},{"id":"c","text":"パターンマッチング法"},{"id":"d","text":"ビヘイビア法"}]','"d"','ビヘイビア法はプログラムを実行した際の振る舞いを観察して検出する。ほかの選択肢は主にデータ比較や既知パターンなどを用いる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q04','exam-sg','サイバー攻撃・攻撃段階','standard','single_choice','サイバーキルチェーンに関する説明として，適切なものはどれか。','[{"id":"a","text":"委託先の情報セキュリティリスクが委託元にも影響するという考え方を基にしたリスク分析のこと"},{"id":"b","text":"攻撃者がクライアントとサーバとの間の通信を中継し，直接通信しているかのように装う攻撃手法のこと"},{"id":"c","text":"攻撃者の視点から，攻撃の手口を偵察から目的の実行までの段階に分けたもの"},{"id":"d","text":"取引データを時系列につなげ，改ざんを検知可能にする保存方式のこと"}]','"c"','サイバーキルチェーンは攻撃を偵察，武器化，配送，侵入，インストール，遠隔操作，目的実行などの段階に分けて捉えるモデルである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q05','exam-sg','認証・リスクベース認証','standard','single_choice','リスクベース認証の説明として，適切なものはどれか。','[{"id":"a","text":"機器の画面に表示された点を正しい順序に一筆書きでなぞった場合，認証が成功し，機器のロックが解除される。"},{"id":"b","text":"通常とは異なる IP アドレス，Web ブラウザなどから認証要求があった場合に，追加の認証を行う。"},{"id":"c","text":"認証局が，Web サイトへのサーバ証明書発行において，サーバ証明書に記載される組織のドメイン利用権，法的及び物理的実在性を確認する。"},{"id":"d","text":"ゆがんだ文字を含む画像を表示し，その文字が正しく入力された場合に認証が成功する。"}]','"b"','リスクベース認証は接続元や端末，利用状況などのリスクを評価し，通常と異なる場合に追加認証などを要求する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q06','exam-sg','TLS・サーバ証明書','standard','single_choice','PCからWebサーバへTLSでアクセスする際，PCがサーバ証明書を入手した後に，認証局の公開鍵を利用して行う動作はどれか。','[{"id":"a","text":"暗号化通信に利用する共通鍵を，認証局の公開鍵を使って復号する。"},{"id":"b","text":"暗号化通信に利用する共通鍵を生成し，認証局の公開鍵を使って暗号化する。"},{"id":"c","text":"サーバ証明書の正当性を，認証局の公開鍵を使って検証する。"},{"id":"d","text":"利用者が入力して送付する秘匿データを，認証局の公開鍵を使って暗号化する。"}]','"c"','認証局の公開鍵は，サーバ証明書に付された認証局の署名を検証し，証明書の正当性を確認するために利用する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q07','exam-sg','法務・個人情報保護法','standard','single_choice','個人情報保護法が保護の対象としている個人情報に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"企業が管理している顧客に関する情報に限られる"},{"id":"b","text":"個人が秘密にしているプライバシーに関する情報に限られる"},{"id":"c","text":"生存する個人に関する情報に限られる"},{"id":"d","text":"日本国籍を有する個人に関する情報に限られる"}]','"c"','個人情報保護法上の個人情報は生存する個人に関する情報が対象であり，顧客情報や秘密情報，日本国籍に限定されない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q08','exam-sg','内部統制・統制活動','standard','single_choice','内部統制の基本的要素の一つである「統制活動」に該当するものはどれか。','[{"id":"a","text":"経営目的を達成するための経営方針及び経営戦略"},{"id":"b","text":"個人情報保護に関する脅威と脆弱性の分析"},{"id":"c","text":"受注から出荷に至る業務プロセスに組み込まれた処理結果の検証"},{"id":"d","text":"定期的に計画して実施する内部業務監査"}]','"c"','統制活動は，承認，照合，検証，職務分掌など，リスクに対処するため業務プロセスに組み込まれた具体的な統制手続を指す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q09','exam-sg','システム信頼性・可用性','standard','single_choice','システムの信頼性指標として RASIS がある。そのうちの A は可用性を表し，システムのサービス時間など，ある一定期間でのシステムの機能を維持する度合いを表している。この A を向上させるものはどれか。','[{"id":"a","text":"MTBF と MTTR をともに 2 倍にする。"},{"id":"b","text":"MTBF は変えず，MTTR を 2 倍にする。"},{"id":"c","text":"MTBF を 2 倍にして，MTTR は変えない。"},{"id":"d","text":"MTBF を半分にして，MTTR は 2 倍にする。"}]','"c"','可用性は概ね MTBF ÷（MTBF + MTTR）で表される。平均故障間隔を長くし，修復時間を変えなければ可用性は向上する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q10','exam-sg','ネットワーク・プロキシサーバ','standard','single_choice','社内ネットワークからインターネットへのアクセスを中継し，Webコンテンツをキャッシュしてアクセスを高速化し，セキュリティ確保にも利用されるものはどれか。','[{"id":"a","text":"DMZ"},{"id":"b","text":"IPマスカレード（NAPT）"},{"id":"c","text":"ファイアウォール"},{"id":"d","text":"プロキシサーバ"}]','"d"','プロキシサーバはクライアントの代わりに外部へアクセスし，キャッシュやアクセス制御，ログ取得などに利用できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q11','exam-sg','業務改善・RPA導入','standard','single_choice','全社的な推進体制でRPAを導入するときの留意点として，適切なものはどれか。','[{"id":"a","text":"各業務部門が連携して，RPA の対象業務に対して業務プロセス全体の可視化と業務プロセスの見直しを行った上で，RPA の導入を行う。"},{"id":"b","text":"業務フローが固定的で画面の変更が少ない業務よりも，業務フローの変更や画面の変更が多い業務から優先的に導入する。"},{"id":"c","text":"情報システム部門や他部門との連携は行わずに，個々の業務部門が主導して，RPA ツールの選定，ソフトウェアロボットの作成，活用及び運用を推進する。"},{"id":"d","text":"ルール化された処理や繰返し処理が多い業務よりも，例外処理が多い業務や条件が複雑な業務に対して，優先的に RPA の導入を行う。"}]','"a"','RPA導入前に業務プロセス全体を可視化し，必要な業務見直しを行い，業務部門と情報システム部門などが連携して進める。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja'),
('sg-official-r06-2024-q12','exam-sg','品質管理・特性要因図','standard','single_choice','特性要因図を説明したものはどれか。','[{"id":"a","text":"原因と結果の関連を魚の骨のような形態に整理して体系的にまとめ，結果に対してどのような原因が関連しているかを明確にする。"},{"id":"b","text":"時系列的に発生するデータのばらつきを折れ線グラフで表し，管理限界線を利用して客観的に管理する。"},{"id":"c","text":"収集したデータを幾つかの区間に分類し，各区間に属するデータの個数を棒グラフとして描き，品質のばらつきを捉える。"},{"id":"d","text":"データを幾つかの項目に分類し，出現頻度の大きさの順に棒グラフとして並べ，累積和を折れ線グラフで描き，問題点を絞り込む。"}]','"a"','特性要因図（魚の骨図）は結果とその原因の関係を整理する図である。管理図，ヒストグラム，パレート図とは目的が異なる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/eid2eo0000007g1d-att/2024r06_sg_qs.pdf','ja');
